$ErrorActionPreference='Continue'
$r='C:\Users\Xxkan\mhw-mods-work-canonical'
& git -C $r fetch origin --prune '+refs/heads/*:refs/remotes/origin/*' 2>$null | Out-Null
$rows=@()
foreach($ref in @(& git -C $r for-each-ref --format='%(refname)' refs/remotes/origin/)){
 if($ref -notmatch '^refs/remotes/origin/(.+)$'){continue}
 $b=$Matches[1]
 if(!$b -or $b -in @('HEAD','main','heaven-bridge')){continue}
 $mb=(& git -C $r merge-base origin/main "origin/$b" 2>$null).Trim()
 if(!$mb){continue}
 $files=@(& git -C $r diff --name-only "$mb..origin/$b" --)
 $commits=@(& git -C $r log --format='%h|%s' --no-merges "origin/main..origin/$b")
 $code=@($files|Where-Object{$_ -match '^(src|tests|tools|scripts|heaven-bridge|\.github)/'}).Count
 $context=@($files|Where-Object{$_ -match '^(_AGENT_CONTEXT|\.verification|NEXT-AGENT-START-HERE\.md|README\.md$|CHANGELOG\.md$|VERSION\.txt$|Directory\.Build\.props$)'}).Count
 $rows += [pscustomobject]@{branch=$b; commits=$commits.Count; files=$files.Count; code_files=$code; context_files=$context; file_list=($files -join ','); messages=(($commits|Select-Object -First 8)-join ' || ')}
}
$rows | ConvertTo-Json -Depth 4 -Compress
